select null, t.id, 'builtin', 'The Bombay (Oh) phenotype is defined by the absence of which antigen on red cells?', '["A antigen only","B antigen only","H antigen","D antigen"]'::jsonb, 2, 'Bombay individuals (hh) cannot make H antigen, the precursor of A and B, so they have no A, B, or H antigens and produce anti-A, anti-B, and anti-H. Reference: Dean, Blood Groups and Red Cell Antigens, The Hh blood group (ncbi.nlm.nih.gov/books/NBK2268).', '["A and B are also missing, but the defining loss is H.","A and B are also missing, but the defining loss is H.","No H (FUT1 defect), so A and B cannot be made; plasma has anti-H.","Rh antigen; unrelated to the Bombay phenotype."]'::jsonb, 2, 'verified'
