select null, t.id, 'builtin', 'Which of these syphilis tests is nontreponemal?', '["TP-PA","FTA-ABS","RPR","Treponemal EIA"]'::jsonb, 2, 'RPR and VDRL are nontreponemal tests. TP-PA, FTA-ABS, and EIAs/CIAs detect antibodies to Treponema pallidum itself. A presumptive diagnosis needs one test of each kind. Reference: CDC STI Treatment Guidelines, Syphilis (cdc.gov/std/treatment-guidelines/syphilis.htm).', '["Treponemal test (detects antibody to T. pallidum).","Treponemal test; stays positive for life.","Detects antibody to cardiolipin (reagin), not to the treponeme itself.","Treponemal test."]'::jsonb, 1, 'verified'
