select null, t.id, 'builtin', 'The most frequent cause of an acute hemolytic transfusion reaction is:', '["Bacterial contamination of the unit","ABO incompatibility from a clerical error or patient misidentification","Anti-IgA antibodies in the recipient","Circulatory overload"]'::jsonb, 1, 'Most acute hemolytic reactions come from ABO-incompatible blood given because of a clerical error or wrong patient identification. Anti-IgA causes anaphylaxis, and overload is TACO. Reference: What every physician should know about transfusion reactions (pmc.ncbi.nlm.nih.gov/articles/PMC1913131); StatPearls, ABO Blood Group System (ncbi.nlm.nih.gov/books/NBK580518).', '["Causes fever and shock (septic reaction), less common.","Wrong patient or wrong unit is the main cause; IgM anti-A/B lyses cells.","Causes anaphylaxis, not hemolysis.","TACO; not hemolytic."]'::jsonb, 1, 'verified'
