select null, t.id, 'builtin', 'A group A secretor will have which blood group substances in saliva?', '["A only","A and H","H only","Neither A nor H"]'::jsonb, 1, 'In group A secretors, A and H antigens are found in saliva. The FUT2 (Se) gene encodes the fucosyltransferase used in secretions. Reference: Use of a recombinant deacetylase to convert A1 red blood cells to the acquired B phenotype (pmc.ncbi.nlm.nih.gov/articles/PMC10920065); ABO blood groups and galectins: Implications in transfusion medicine and innate immunity (pmc.ncbi.nlm.nih.gov/articles/PMC11808837).', '["A secretor also secretes H, the precursor.","Se gene lets H and A appear in secretions.","Group O secretors have only H.","That is a nonsecretor."]'::jsonb, 2, 'verified'
