insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'The "acquired B" phenomenon is associated with:', '["Group O persons with leukemia","Group B newborns","Group A1 persons with certain bacterial infections","Group AB persons during pregnancy"]'::jsonb, 2, 'Bacterial enzymes can change the A sugar into a B-like structure, so group A1 cells react weakly with anti-B. The change stops once the infection clears. Reference: Use of a recombinant deacetylase to convert A1 red blood cells to the acquired B phenotype (pmc.ncbi.nlm.nih.gov/articles/PMC10920065).', '["Not the usual setting.","Not the usual setting.","Bacterial deacetylase turns A sugar into one like B (e.g., colon cancer, gut infection).","Not the usual setting."]'::jsonb, 3, 'verified'
