insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'The universal donor for PLASMA is group:', '["O","A","B","AB"]'::jsonb, 3, 'Group AB serum contains neither anti-A nor anti-B, so AB plasma can be given to any ABO group. For red cells, group O is the universal donor. Reference: ABO blood groups and galectins: Implications in transfusion medicine and innate immunity (pmc.ncbi.nlm.nih.gov/articles/PMC11808837).', '["Group O plasma has anti-A and anti-B; O is the red cell universal donor.","Has anti-B.","Has anti-A.","AB plasma has no anti-A or anti-B."]'::jsonb, 1, 'verified'
