where s.code = 'BBIS' and t.name = 'ABO & H System'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('The universal donor for PLASMA is group:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Group O plasma has anti-A and anti-B; O is the red cell universal donor.","Has anti-B.","Has anti-A.","AB plasma has no anti-A or anti-B."]'::jsonb
