insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Anti-A and anti-B antibodies develop naturally:', '["Before birth, in the fetus","During the first few months of life","Only after a transfusion","Only after pregnancy"]'::jsonb, 1, 'ABO antibodies develop naturally during the first few months of life, which is why reverse typing is not reliable in newborns. Reference: ABO blood groups and galectins: Implications in transfusion medicine and innate immunity (pmc.ncbi.nlm.nih.gov/articles/PMC11808837).', '["Newborns have little or no ABO antibody of their own.","Start at about 3–6 months from exposure to similar antigens in gut bacteria.","They are present without any transfusion.","They are present without pregnancy."]'::jsonb, 2, 'verified'
