insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Weak D differs from partial D because weak D has:', '["Fewer D antigen sites (a quantitative change)","Missing D epitopes","No D antigen at all","An extra RHD gene"]'::jsonb, 0, 'Weak D is a quantitative weakening of the D antigen. In partial D, single epitopes of D are lost, so these persons can form anti-D. Reference: Flegel, The genetics of the Rhesus blood group system, Blood Transfus 2007 (pmc.ncbi.nlm.nih.gov/articles/PMC2535884).', '["Normal D epitopes but fewer of them; usually does not make anti-D.","That describes partial D.","That describes D-negative.","Not the definition."]'::jsonb, 2, 'verified'
