insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'The most immunogenic Rh antigen is:', '["C","D","E","e"]'::jsonb, 1, 'Of the Rh antigens, D is the most immunogenic, which is why D-negative persons get D-negative blood and RhIG in pregnancy. Reference: OpenStax Microbiology, 19.1 Hypersensitivities (openstax.org/books/microbiology/pages/19-1-hypersensitivities).', '["Less immunogenic than D.","Very immunogenic; most D-negative people exposed make anti-D.","Less immunogenic than D.","Less immunogenic than D."]'::jsonb, 1, 'verified'
