insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'An Rh-null phenotype can result from a defect in which gene needed for Rh protein expression?', '["RHAG","ABO","FUT1","KEL"]'::jsonb, 0, 'Rh-null red cells lack Rh antigens; one cause is a defect in the RHAG gene, whose protein is needed for Rh proteins to reach the membrane. Reference: Flegel, The genetics of the Rhesus blood group system, Blood Transfus 2007 (pmc.ncbi.nlm.nih.gov/articles/PMC2535884).', '["RHAG is needed to carry Rh proteins to the membrane.","Controls A and B transferases.","Controls H antigen (Bombay when absent).","Kell blood group gene."]'::jsonb, 3, 'verified'
