insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Rh antigens are carried on:', '["Glycolipids","Plasma proteins adsorbed onto the cells","Carbohydrate chains on glycophorin","Transmembrane proteins encoded by RHD and RHCE"]'::jsonb, 3, 'The Rh antigens are on two membrane proteins, RhD and RhCE, each crossing the membrane 12 times, encoded by RHD and RHCE on chromosome 1. Reference: Flegel, The genetics of the Rhesus blood group system, Blood Transfus 2007 (pmc.ncbi.nlm.nih.gov/articles/PMC2535884).', '["Those carry ABO, Lewis and P antigens.","Lewis antigens are adsorbed from plasma.","Carry MN antigens.","Nonglycosylated proteins that cross the membrane many times."]'::jsonb, 2, 'verified'
