select null, t.id, 'builtin', 'One full-dose vial (300 micrograms) of Rh immune globulin protects against a fetomaternal hemorrhage of about:', '["5 mL of whole blood","15 mL of whole blood","30 mL of whole blood","100 mL of whole blood"]'::jsonb, 2, 'One 1500 IU (300 microgram) dose of anti-D is enough to neutralize 30 mL of fetal whole blood. Reference: FIGO/ICM guidelines for preventing Rhesus disease: A call to action (pmc.ncbi.nlm.nih.gov/articles/PMC7898700).', '["Too small.","That is the volume of packed red cells covered (15 mL).","Covers about 30 mL of fetal whole blood (15 mL red cells).","Too large; more vials would be needed."]'::jsonb, 2, 'verified'
