insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Persons with a partial D phenotype:', '["Can make anti-D against the D epitopes they lack","Never make anti-D","Always type as D-negative","Lack all Rh antigens"]'::jsonb, 0, 'In partial D, single epitopes of the D antigen are lost, so these persons can form anti-D after exposure to normal D. Reference: Flegel, The genetics of the Rhesus blood group system, Blood Transfus 2007 (pmc.ncbi.nlm.nih.gov/articles/PMC2535884).', '["Missing parts of D, so exposure to normal D can trigger anti-D.","They can make anti-D.","They usually type D-positive.","That is Rh-null."]'::jsonb, 3, 'verified'
