insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'For transfusion, a patient with a partial D phenotype is usually typed and managed as:', '["D-negative","D-positive","Rh-null","Weak D, so any blood is safe"]'::jsonb, 0, 'Partial D patients are treated as D-negative for transfusion to avoid anti-D, but as D-positive when they donate. Reference: Integrating RHD Genotyping for More Accurate Rh(D) Antigen Phenotyping (pmc.ncbi.nlm.nih.gov/articles/PMC12028936).', '["Treated as D-negative to avoid anti-D formation.","Risk of making anti-D if given D-positive blood.","Rh-null lacks all Rh antigens.","Partial D is not weak D, and it can still make anti-D."]'::jsonb, 3, 'verified'
