insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'In an acute hemolytic transfusion reaction, the post-reaction direct antiglobulin test (DAT) is usually:', '["Positive","Negative","Not useful","Positive only with anti-IgE"]'::jsonb, 0, 'The DAT is usually positive, except rarely when all incompatible red cells have already been destroyed. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Donor cells coated with antibody give a positive DAT, unless they are already lysed.","Usually positive, though it can be negative if all coated cells are destroyed.","It is a key test in the reaction workup.","No anti-IgE AHG test exists for this."]'::jsonb, 1, 'verified'
