  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('In an acute hemolytic transfusion reaction, the post-reaction direct antiglobulin test (DAT) is usually:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
