insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'In cold agglutinin disease, the DAT is typically positive with:', '["Anti-IgG only","Anti-C3d (complement) only","Neither reagent","Anti-IgA only"]'::jsonb, 1, 'In cold agglutinin disease the DAT is positive for C3d, with IgG negative or only weakly positive. Reference: The role of serological and molecular testing in the diagnostics and transfusion treatment of AIHA (pmc.ncbi.nlm.nih.gov/articles/PMC9256513); Berentsen, Cold agglutinin disease, Hematology Am Soc Hematol Educ Program 2016 (pmc.ncbi.nlm.nih.gov/articles/PMC6142439).', '["Seen in warm AIHA.","IgM cold antibody fixes complement, then falls off, leaving C3d.","The DAT is positive.","Not typical."]'::jsonb, 2, 'verified'
