  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('In cold agglutinin disease, the DAT is typically positive with:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Seen in warm AIHA.","IgM cold antibody fixes complement, then falls off, leaving C3d.","The DAT is positive.","Not typical."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Anti-IgG only","Anti-C3d (complement) only","Neither reagent","Anti-IgA only"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('In cold agglutinin disease, the DAT is typically positive with:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
