  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('An elution procedure is used to:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Not the purpose.","That is sensitization.","Freed antibody (eluate) is then identified with panel cells.","Not the purpose."]'::jsonb
