insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Red blood cell units are stored at:', '["20 to 24 C","1 to 6 C","-18 C or colder","37 C"]'::jsonb, 1, 'Red-cell-containing components are stored at 1 to 6 C. Conventional platelets are kept at 20 to 24 C. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Platelet storage temperature.","Keeps red cells for up to 35–42 days, depending on the solution.","Plasma storage temperature.","Too warm."]'::jsonb, 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Blood Components & Storage'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Red blood cell units are stored at:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Platelet storage temperature.","Keeps red cells for up to 35–42 days, depending on the solution.","Plasma storage temperature.","Too warm."]'::jsonb
