insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Fresh frozen plasma is stored frozen at:', '["1 to 6 C","20 to 24 C","-18 C or colder","37 C"]'::jsonb, 2, 'FFP is frozen at -18 C or colder. After thawing it is kept at 1 to 6 C and used within 24 hours. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Red cell storage temperature.","Platelet storage temperature.","Frozen within 8 hours of collection; keeps up to 1 year.","Too warm."]'::jsonb, 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Blood Components & Storage'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Fresh frozen plasma is stored frozen at:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Red cell storage temperature.","Platelet storage temperature.","Frozen within 8 hours of collection; keeps up to 1 year.","Too warm."]'::jsonb
