insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Red cells collected in CPDA-1 expire after:', '["42 days","21 days","5 days","35 days"]'::jsonb, 3, 'CPDA-1 gives red cells a shelf life of 35 days (adenine supports ATP). Red cells in additive solutions last 42 days. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Red cells in additive solutions (e.g., AS-1) last 42 days.","CPD or ACD red cells last 21 days.","Platelet shelf life.","Adenine helps red cells make ATP, extending storage."]'::jsonb, 1, 'verified'
