select null, t.id, 'builtin', 'Cryoprecipitate is a source of:', '["Fibrinogen, factor VIII, vWF and factor XIII","Albumin and immunoglobulins","Factors VII and IX","Platelets"]'::jsonb, 0, 'Cryoprecipitated AHF contains fibrinogen, factor VIII, factor XIII and vWF. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Made by thawing FFP at 1–6 °C; used for low fibrinogen.","Albumin and IVIG come from fractionation.","Factor IX and VII are in plasma, not cryo.","Platelets are a separate component."]'::jsonb, 2, 'verified'
