update questions set choice_notes = '["Made by thawing FFP at 1–6 °C; used for low fibrinogen.","Albumin and IVIG come from fractionation.","Factor IX and VII are in plasma, not cryo.","Platelets are a separate component."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Fibrinogen, factor VIII, vWF and factor XIII","Albumin and immunoglobulins","Factors VII and IX","Platelets"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Cryoprecipitate is a source of:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Blood components are irradiated mainly to prevent:', '["Febrile reactions","Transfusion-associated graft-versus-host disease","CMV transmission","Allergic reactions"]'::jsonb, 1, 'Irradiation makes donor T lymphocytes unable to proliferate, preventing transfusion-associated graft-vs-host disease. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Leukocyte reduction helps prevent these.","Kills donor T cells so they cannot attack the recipient.","Leukocyte reduction or CMV-negative units lower this risk.","Washing or antihistamines help with these."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Blood Components & Storage'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Blood components are irradiated mainly to prevent:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Leukocyte reduction helps prevent these.","Kills donor T cells so they cannot attack the recipient.","Leukocyte reduction or CMV-negative units lower this risk.","Washing or antihistamines help with these."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Febrile reactions","Transfusion-associated graft-versus-host disease","CMV transmission","Allergic reactions"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Blood components are irradiated mainly to prevent:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Leukocyte reduction lowers the risk of all of the following EXCEPT:', '["Febrile nonhemolytic reactions","HLA alloimmunization","CMV transmission","Transfusion-associated GVHD"]'::jsonb, 3, 'Leukocyte-reduced components lower febrile reactions, CMV transmission and HLA alloimmunization, but they do not prevent TA-GVHD; irradiation does. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Reduced, since white cell cytokines cause fever.","Reduced, since fewer HLA-bearing white cells are given.","Reduced, since CMV lives in white cells.","Only irradiation prevents TA-GVHD; a few T cells can still remain."]'::jsonb, 3, 'verified'
