update questions set choice_notes = '["Reduced, since white cell cytokines cause fever.","Reduced, since fewer HLA-bearing white cells are given.","Reduced, since CMV lives in white cells.","Only irradiation prevents TA-GVHD; a few T cells can still remain."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Febrile nonhemolytic reactions","HLA alloimmunization","CMV transmission","Transfusion-associated GVHD"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Leukocyte reduction lowers the risk of all of the following EXCEPT:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Washed red cells may be used for patients with:', '["Iron deficiency","Hemophilia A","IgA deficiency with anti-IgA, or severe repeated allergic reactions","Thrombocytopenia"]'::jsonb, 2, 'Washing removes plasma proteins, so it can be used for IgA-deficient recipients or patients with repeated anaphylactic reactions to plasma. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Treated with iron, not washed cells.","Treated with factor VIII.","Washing removes plasma proteins such as IgA.","Needs platelets."]'::jsonb, 2, 'verified'
