update questions set choice_notes = '["Treated with iron, not washed cells.","Treated with factor VIII.","Washing removes plasma proteins such as IgA.","Needs platelets."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Iron deficiency","Hemophilia A","IgA deficiency with anti-IgA, or severe repeated allergic reactions","Thrombocytopenia"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Washed red cells may be used for patients with:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Irradiated red cells, compared with nonirradiated ones, have higher:', '["Supernatant potassium","Platelet count","Fibrinogen","Factor VIII"]'::jsonb, 0, 'Irradiated red cells have higher supernatant potassium, so their expiration date is shortened. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Radiation damages red cell membranes, so potassium leaks out.","Red cell units contain almost no platelets.","Not in red cell units in any useful amount.","Not in red cell units in any useful amount."]'::jsonb, 2, 'verified'
