insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'One whole-blood-derived platelet unit should raise the platelet count of a 70-kg adult by about:', '["1,000/uL","5,000 to 10,000/uL","50,000/uL","100,000/uL"]'::jsonb, 1, 'One whole-blood-derived platelet unit raises a 70-kg adult''s count by 5,000 to 10,000/uL; an apheresis unit by about 30,000 to 60,000/uL. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Too small.","An apheresis unit raises it by about 30,000–60,000/µL.","Closer to an apheresis unit''s increase.","Too large."]'::jsonb, 2, 'verified'
