insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'A temperature rise of at least 1 C during transfusion with no signs of hemolysis is most likely a:', '["Acute hemolytic reaction","Febrile nonhemolytic transfusion reaction","TRALI","Anaphylactic reaction"]'::jsonb, 1, 'A febrile nonhemolytic reaction is a temperature rise of 1 C or more (or chills) during or within 4 hours of transfusion with no other cause. Hemovigilance defines fever as 38 C or higher. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf); CDC NHSN Biovigilance Component, Hemovigilance Module Protocol (cdc.gov/nhsn/pdfs/biovigilance/bv-hv-protocol-current.pdf).', '["Hemolysis would show a positive DAT, hemoglobinuria and so on.","White cell cytokines cause fever; leukoreduction prevents it.","Shows acute lung injury within 6 hours.","Shows hypotension and breathing problems, no fever."]'::jsonb, 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Transfusion Reactions & HDFN'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('A temperature rise of at least 1 C during transfusion with no signs of hemolysis is most likely a:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Hemolysis would show a positive DAT, hemoglobinuria and so on.","White cell cytokines cause fever; leukoreduction prevents it.","Shows acute lung injury within 6 hours.","Shows hypotension and breathing problems, no fever."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Acute hemolytic reaction","Febrile nonhemolytic transfusion reaction","TRALI","Anaphylactic reaction"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('A temperature rise of at least 1 C during transfusion with no signs of hemolysis is most likely a:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Severe anaphylaxis after only a few mL of plasma in an IgA-deficient patient is due to:', '["Anti-IgA antibodies in the patient","Anti-HLA antibodies in the donor","Anti-Jka in the patient","Bacterial contamination"]'::jsonb, 0, 'Anaphylactic reactions have been reported in IgA-deficient patients with anti-IgA, although most anaphylactic reactions have no identifiable cause. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["IgA-deficient patients can make anti-IgA; give IgA-deficient or washed products.","Causes TRALI.","Causes delayed hemolytic reactions.","Causes fever and shock."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Transfusion Reactions & HDFN'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Severe anaphylaxis after only a few mL of plasma in an IgA-deficient patient is due to:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["IgA-deficient patients can make anti-IgA; give IgA-deficient or washed products.","Causes TRALI.","Causes delayed hemolytic reactions.","Causes fever and shock."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Anti-IgA antibodies in the patient","Anti-HLA antibodies in the donor","Anti-Jka in the patient","Bacterial contamination"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Severe anaphylaxis after only a few mL of plasma in an IgA-deficient patient is due to:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Transfusion-related acute lung injury (TRALI) is most often caused by:', '["Recipient anti-IgA","Donor anti-HLA or anti-neutrophil antibodies","Too much volume","Bacterial contamination"]'::jsonb, 1, 'TRALI is hypoxemia with noncardiogenic pulmonary edema within 6 hours of transfusion, most often from donor white-cell antibodies. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["That causes anaphylaxis.","Antibodies in donor plasma activate the recipient''s neutrophils in the lung.","That is TACO.","That is a septic reaction."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Transfusion Reactions & HDFN'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Transfusion-related acute lung injury (TRALI) is most often caused by:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["That causes anaphylaxis.","Antibodies in donor plasma activate the recipient''s neutrophils in the lung.","That is TACO.","That is a septic reaction."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Recipient anti-IgA","Donor anti-HLA or anti-neutrophil antibodies","Too much volume","Bacterial contamination"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Transfusion-related acute lung injury (TRALI) is most often caused by:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'New respiratory distress with evidence of volume overload after a large or rapid transfusion suggests:', '["Febrile nonhemolytic reaction","Urticarial reaction","TRALI","Transfusion-associated circulatory overload (TACO)"]'::jsonb, 3, 'TACO is cardiogenic pulmonary edema from transfusing too much volume or too fast. Patients with heart or kidney disease and the elderly are at risk. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["Fever with no volume overload.","Hives and itching.","Lung injury without fluid overload; antibody-mediated.","Too much volume too fast; often high blood pressure; responds to diuretics."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Transfusion Reactions & HDFN'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('New respiratory distress with evidence of volume overload after a large or rapid transfusion suggests:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Fever with no volume overload.","Hives and itching.","Lung injury without fluid overload; antibody-mediated.","Too much volume too fast; often high blood pressure; responds to diuretics."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Febrile nonhemolytic reaction","Urticarial reaction","TRALI","Transfusion-associated circulatory overload (TACO)"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('New respiratory distress with evidence of volume overload after a large or rapid transfusion suggests:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Delayed hemolytic transfusion reactions usually occur how long after transfusion?', '["Within 1 hour","2 to 14 days","6 months","Only during the transfusion"]'::jsonb, 1, 'In previously alloimmunized patients, an anamnestic antibody response destroys the transfused cells, usually 2 to 14 days after transfusion. Reference: AABB et al., Circular of Information for the Use of Human Blood and Blood Components, June 2024 (weareblood.org/wp-content/uploads/2024/10/Circular-of-Information-for-the-Use-of-Human-Blood-and-Blood-Components-June-2024.pdf).', '["That is an acute reaction.","Anamnestic response from an earlier exposure (often Kidd antibodies).","Too late.","That is an acute reaction."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Transfusion Reactions & HDFN'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Delayed hemolytic transfusion reactions usually occur how long after transfusion?'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["That is an acute reaction.","Anamnestic response from an earlier exposure (often Kidd antibodies).","Too late.","That is an acute reaction."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Within 1 hour","2 to 14 days","6 months","Only during the transfusion"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Delayed hemolytic transfusion reactions usually occur how long after transfusion?'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
