select null, t.id, 'builtin', 'Which immunoglobulin is the only one that crosses the placenta?', '["IgA","IgM","IgG","IgE"]'::jsonb, 2, 'IgG is the only antibody class that can cross the placenta, which is why it protects the newborn and can cause HDFN. Reference: OpenStax Microbiology, 18.1 Overview of Specific Adaptive Immunity (openstax.org/books/microbiology/pages/18-1-overview-of-specific-adaptive-immunity).', '["Does not cross the placenta.","Too large to cross the placenta.","Crosses the placenta through FcRn receptors.","Does not cross the placenta."]'::jsonb, 1, 'verified'
