select null, t.id, 'builtin', 'Which immunoglobulin predominates in tears, saliva and breast milk?', '["IgA","IgD","IgE","IgG"]'::jsonb, 0, 'Secretory IgA is the most abundant antibody class in mucus secretions and is also found in breast milk, tears and saliva. Reference: OpenStax Microbiology, 18.1 Overview of Specific Adaptive Immunity (openstax.org/books/microbiology/pages/18-1-overview-of-specific-adaptive-immunity).', '["Secretory IgA is a dimer that protects mucous membranes.","Mainly a B-cell receptor.","Allergy antibody.","Main antibody in serum, not secretions."]'::jsonb, 1, 'verified'
