from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Serologic Tests'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Which hepatitis B marker indicates recent infection (within about 6 months)?'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Shows immunity.","IgM to the core antigen marks an infection within about 6 months.","Not a usual marker of recent infection.","IgM anti-HBc is the marker."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Anti-HBs","IgM anti-HBc","HBsAg with anti-HBs","None of these"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Which hepatitis B marker indicates recent infection (within about 6 months)?'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'A person vaccinated against hepatitis B who was never infected is positive only for:', '["HBsAg","Anti-HBc","HBeAg","Anti-HBs"]'::jsonb, 3, 'HBsAg negative, anti-HBc negative and anti-HBs positive means immune due to hepatitis B vaccination. Anti-HBc appears only after natural infection. Reference: CDC, Interpretation of Hepatitis B Serologic Test Results (cdc.gov/hepatitis-b/media/serologicchartv8.pdf).', '["Means current infection.","Means past or current infection.","Means active viral replication.","The vaccine has only HBsAg, so only anti-HBs forms."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Serologic Tests'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('A person vaccinated against hepatitis B who was never infected is positive only for:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Means current infection.","Means past or current infection.","Means active viral replication.","The vaccine has only HBsAg, so only anti-HBs forms."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["HBsAg","Anti-HBc","HBeAg","Anti-HBs"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('A person vaccinated against hepatitis B who was never infected is positive only for:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'C-reactive protein is:', '["An acute-phase protein made by the liver","An antibody against streptococci","A complement component","A protein made by plasma cells"]'::jsonb, 0, 'The liver makes CRP in response to inflammation, and its level rises and falls with the amount of inflammation. Reference: MedlinePlus Lab Tests, C-Reactive Protein (CRP) Test (medlineplus.gov/lab-tests/c-reactive-protein-crp-test).', '["Rises within hours of inflammation, infection or injury.","That is ASO.","Not part of complement, though it can activate it.","Made by the liver."]'::jsonb, 1, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Serologic Tests'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('C-reactive protein is:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["Rises within hours of inflammation, infection or injury.","That is ASO.","Not part of complement, though it can activate it.","Made by the liver."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["An acute-phase protein made by the liver","An antibody against streptococci","A complement component","A protein made by plasma cells"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('C-reactive protein is:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'In the CDC laboratory HIV testing algorithm, the recommended initial test is a(n):', '["Western blot","HIV-1/2 antigen/antibody combination immunoassay","CD4 count","Viral culture"]'::jsonb, 1, 'CDC recommends starting with an HIV-1/2 antigen/antibody combination immunoassay; reactive results go to an antibody differentiation assay. Western blot is no longer used. Reference: CDC & APHL, Laboratory Testing for the Diagnosis of HIV Infection: Updated Recommendations, 2014 (stacks.cdc.gov/view/cdc/23447).', '["No longer used in the CDC algorithm.","4th-generation test detects p24 antigen and antibodies, so it finds infection earlier.","Shows immune status, not infection.","Not used for routine diagnosis."]'::jsonb, 2, 'verified'
from topics t join subjects s on s.id = t.subject_id
where s.code = 'BBIS' and t.name = 'Serologic Tests'
  and not exists (select 1 from questions x where x.owner_id is null and x.stem_hash = md5(trim(regexp_replace(regexp_replace(lower('In the CDC laboratory HIV testing algorithm, the recommended initial test is a(n):'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g'))));
update questions set choice_notes = '["No longer used in the CDC algorithm.","4th-generation test detects p24 antigen and antibodies, so it finds infection earlier.","Shows immune status, not infection.","Not used for routine diagnosis."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Western blot","HIV-1/2 antigen/antibody combination immunoassay","CD4 count","Viral culture"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('In the CDC laboratory HIV testing algorithm, the recommended initial test is a(n):'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));
insert into questions (owner_id, topic_id, source, stem, choices, correct_index, explanation, choice_notes, difficulty, status)
select null, t.id, 'builtin', 'Rheumatoid factor is a protein made by the immune system that attacks:', '["Nuclear antigens","Cardiolipin","The patient''s own IgG","Streptolysin O"]'::jsonb, 2, 'Rheumatoid factor is made by the immune system and attacks the body''s own immunoglobulin G (IgG). Reference: MedlinePlus Lab Tests, Rheumatoid Factor (RF) Test (medlineplus.gov/lab-tests/rheumatoid-factor-rf-test).', '["That is antinuclear antibody (ANA).","That is antiphospholipid antibody.","Usually IgM against the Fc part of IgG.","That is ASO."]'::jsonb, 2, 'verified'
