update questions set choice_notes = '["That is antinuclear antibody (ANA).","That is antiphospholipid antibody.","Usually IgM against the Fc part of IgG.","That is ASO."]'::jsonb
where owner_id is null and choice_notes is null and choices = '["Nuclear antigens","Cardiolipin","The patient''s own IgG","Streptolysin O"]'::jsonb and stem_hash = md5(trim(regexp_replace(regexp_replace(lower('Rheumatoid factor is a protein made by the immune system that attacks:'), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')));

